import React from 'react';
import { NavContainer, NavLogo, NavRight, NavLinks, NavLink } from './Navbar.styles';
import ThemeToggle from '../ThemeToggle/ThemeToggle';

const Navbar = () => {
  return (
    <NavContainer>
      {/* 1. Logo is moved back to the far left */}
      <NavLogo href="/">YA</NavLogo>

      <NavRight>
        <NavLinks>
          <NavLink href="#home">Home</NavLink>
          <NavLink href="#projects">Projects</NavLink>
          {/* 2. ThemeToggle is now inside the NavLinks group */}
          <ThemeToggle />
        </NavLinks>
      </NavRight>
    </NavContainer>
  );
};

export default Navbar;
